ahora=$(date +"%Y-%m-%d-%H-%M-%S");termino="ciberseguridad";destinobase="AvilaprovPoblaciones.txt";destino1="${ahora}${destinobase}";destino2=$(echo ${ahora} | sed 's/\-//g');destino2=${destino2}${destinobase};destino3=$(echo $destino2 | sed 's/\.txt//g');cat AvilaprovPoblaciones.txt | while IFS=";" read f1 f2 f3 f4;do if [[ "$f1" == "Municipios" ]];then echo "Municipios;Total" >>${destino1};else f4=$(echo ${f4} | sed 's/\.//g');echo "${f1:6};${f4}" >>${destino1};fi;done;cp -- ${destino1} ${destino2};destinobash="${ahora}busq${termino}.sh";csvsql -d ";" --query "SELECT Municipios FROM '${destino3}' WHERE Total >= 1000" ${destino2} | sed 's/\"//g' | grep -v 'Municipios' | while read ayto;do cat 2026-08-15websAytos.csv | while IFS=";" read aytoweb web;do if [[ "${ayto}" == "${aytoweb}" ]];then echo "am start -a android.intent.action.VIEW -d \"https://duckduckgo.com/?t=fpas&q=${termino}+site%3A${web}&ia=web\"" >>${destinobash};fi;done;done;rm ${destino1} ${destino2};bash ${destinobash};rm ${destinobash}
